export function findTasks(input) {
  const words = input.toLowerCase().match(/[a-z0-9]+/g) || [];
  if (!words.length) return [];
  const phrase = ` ${words.join(' ')} `;
  return tasks.map(task => ({task, score: task.words.reduce((score, keyword) =>
    score + (phrase.includes(` ${keyword} `) ? (keyword.includes(' ') ? 3 : 1) : 0), 0)}))
    .filter(result => result.score > 0).sort((a,b) => b.score - a.score).map(result => result.task);
}
